"""Fit a transparent TF-IDF evidence retriever over the project's own sources.

This is retrieval NLP, not generative AI, web search, or an external language model.
"""
import json
from pathlib import Path
import re

from sklearn.feature_extraction.text import TfidfVectorizer

ROOT=Path(__file__).resolve().parents[1]


def main():
    data=json.loads((ROOT/'web/data.json').read_text(encoding='utf-8'))
    ml=json.loads((ROOT/'web/models/benchmark.json').read_text(encoding='utf-8'))
    reco=json.loads((ROOT/'web/models/recommendation-benchmark.json').read_text(encoding='utf-8'))
    selected=next(x for x in ml['test'] if x['model'].endswith('October calibration'))
    svd=next(x for x in reco['test'] if x['method']=='svd');pop=next(x for x in reco['test'] if x['method']=='popularity')
    k=data['markets']['All markets']['full']['kpis']
    base='https://github.com/Pavan-amikula/brandscope/blob/main/'
    chunks=[]
    def add(id,title,text,path):chunks.append(dict(id=id,title=title,text=text,source=base+path))
    add('scope','Project and company scope','BrandScope is an independent portfolio project inspired by a P&G brand management role. It is not P&G employment, a commissioned campaign, an endorsement, or a production retailer integration. No project can guarantee recruitment or prove language proficiency.','docs/ROLE_ALIGNMENT.md')
    add('sweden','Swedish sample and localization','Sweden has eight identified shoppers and 34 purchase orders from a historical UK retailer. Swedish net merchandise sales are GBP 35,166.41. This is too small and unrepresentative for a national Swedish FMCG market estimate. Currency remains GBP. Swedish copy is a draft requiring native review.','docs/METHODS.md')
    add('sales','Sales and returns reconciliation',f"Historical gross merchandise sales are GBP {k['gross_sales']:,.2f}; recorded returns are GBP {k['returns']:,.2f}; net sales are GBP {k['net_sales']:,.2f}. These are source dataset totals, not revenue generated by BrandScope.",'docs/outputs/RESULTS.md')
    add('data','Dataset size, cleaning and license','The source has 541,909 rows. Exact deduplication removes 5,268; merchandise and validity rules exclude another 5,857; 530,784 rows remain. Missing-ID sales remain in totals, but shopper analytics exclude them. UCI Online Retail by Chen (2015), DOI 10.24432/C5BW33, is licensed CC BY 4.0.','DATA_LICENSE.md')
    add('propensity','Machine learning model results and repurchase benchmark',f"Supervised machine learning results: the selected random forest predicts a purchase within 30 days. On the November holdout, average precision is {selected['average_precision']:.4f}, ROC-AUC {selected['roc_auc']:.4f}, and top-20% precision {selected['precision_top20']:.4f}. Purchase propensity is not causal offer response, churn probability, or guaranteed profit.",'docs/outputs/ml-benchmark.json')
    add('splits','Temporal leakage prevention','Supervised training uses March–August customer snapshots with future 30-day labels. September selects the model, October fits sigmoid calibration, and November is the final report month. Features use strictly earlier transactions. Customers can recur across snapshots; the evaluation is temporal, not customer-disjoint.','docs/MODEL_CARD.md')
    add('calibration','Calibration limitations','October sigmoid calibration is frozen before November reporting. November calibrated Brier score is about 0.1870 versus 0.1860 for the raw forest; calibration did not improve that metric. Reliability bins and feature-drift diagnostics show remaining uncertainty. Do not describe these probabilities as reliably calibrated in production.','docs/MODEL_CARD.md')
    add('recommendations','Product recommendation evidence',f"A 32-factor TruncatedSVD recommender learns co-purchase structure from pre-cutoff purchase histories. November hit-rate@5 is {100*svd['hit_rate_at5']:.2f}% versus {100*pop['hit_rate_at5']:.2f}% for popularity. Mean recall@5 is only {100*svd['recall_at5']:.2f}%. The eligible population is known shoppers with at least one novel future product, not all shoppers. Basket-seed inference differs from full-history evaluation.",'docs/outputs/recommendation-benchmark.json')
    add('discount','Why discounts can destroy campaign profit','The planning sandbox includes discounts on purchases that would have happened without marketing. With 2,000 shoppers, 5% baseline conversion, assumed 3 percentage-point gain, GBP 45 order value, 45% margin and GBP 600 cost, a 5% discount gives GBP 255 modelled contribution; 20% discount gives GBP -825. These are assumptions, not realized results.','docs/BRAND_STRATEGY.md')
    add('sample','Sample size and power','The default conversion test needs about 1,059 people per arm, exceeding a total audience of 2,000. This normal approximation uses two-sided alpha 0.05 and 80% power. The primary contribution outcome needs its own variance-based design. A positive commercial scenario does not imply a sufficiently powered test.','docs/METHODS.md')
    add('causal','Uplift and causal marketing','This retail dataset contains no randomized treatment assignment or advertising exposure. A purchase predictor cannot identify who would buy only because of an offer. Uplift modeling, causal campaign ROI and marketing mix modeling require suitable additional data. BrandScope does not fabricate treatment labels or channel spend.','docs/MODEL_CARD.md')
    add('experiment','Analyze randomized experiment results','Experiment lab accepts one row per assigned participant: participant_id, arm (control/treatment), converted (0/1), contribution (GBP). Include nonconverters and all costs. It reports contribution difference, approximate 95% intervals, secondary conversion difference and a 50:50 sample-ratio mismatch check. Duplicate participants are rejected. Synthetic demo results do not constitute a real campaign.','docs/EXPERIMENTS.md')
    add('evidence','How the evidence assistant works','The evidence assistant uses a fitted TF-IDF index to retrieve project passages, show source links and abstain when token similarity is insufficient. It is retrieval NLP, not a generative language model or live internet search. Similarity is not a probability of correctness. It does not send questions to an external provider.','docs/MODEL_CARD.md')
    add('live','Live events and hosting boundary','The local Python app accepts validated HTTP events, deduplicates event IDs, stores them in SQLite and refreshes every two seconds. GitHub Pages uses browser-local event storage. Demonstration events are synthetic and never change historical retail metrics. No existing retailer feed is connected.','docs/VERIFICATION.md')
    add('rfm','RFM shopper segmentation','RFM means recency, frequency and monetary value. Champions have recency at most 30 days and at least three orders; high-value at-risk shoppers have recency above 90 days and top-quartile gross spend. There are five mutually exclusive rules. The all-history at-risk group contains 96 shoppers and about GBP 428k of past gross purchases; this is not recoverable value.','docs/METHODS.md')
    add('strategy','Marketing strategy and next action','Use shopper evidence to choose an audience and a relevant proposition, review consent and wholesale status, model contribution, then run a pre-registered test. Consumer interviews, retailer availability, actual margins and native Swedish review are still needed before activation. Scale only with trustworthy contribution evidence and acceptable guardrails.','docs/BRAND_STRATEGY.md')
    for filename in ['METHODS.md','BRAND_STRATEGY.md','MODEL_CARD.md','EXPERIMENTS.md']:
        path=ROOT/'docs'/filename
        if not path.exists():continue
        section=filename
        for i,paragraph in enumerate(path.read_text(encoding='utf-8').split('\n\n')):
            if paragraph.startswith('#'):section=paragraph.lstrip('# ').strip();continue
            if len(paragraph)<100 or '|' in paragraph or len(paragraph)>1800:continue
            text=re.sub(r'[*`#]','',paragraph).replace('\n',' ')
            add(f'{filename}-{i}',section,text,'docs/'+filename)
    vectorizer=TfidfVectorizer(stop_words='english',lowercase=True,token_pattern=r'(?u)\b\w\w+\b',norm='l2')
    matrix=vectorizer.fit_transform([c['title']+' '+c['text'] for c in chunks]).tocsr()
    vectors=[]
    for i in range(matrix.shape[0]):
        row=matrix.getrow(i);vectors.append([[int(j),float(v)] for j,v in zip(row.indices,row.data)])
    artifact=dict(schema_version=1,version='evidence-tfidf-1.0',threshold=.14,chunks=chunks,
        vocabulary={k:int(v) for k,v in vectorizer.vocabulary_.items()},idf=vectorizer.idf_.tolist(),vectors=vectors,
        stop_words=sorted(vectorizer.get_stop_words()),scope='English project evidence only; retrieval NLP, not generative AI')
    (ROOT/'web/models/knowledge.json').write_text(json.dumps(artifact,separators=(',',':'),allow_nan=False),encoding='utf-8')
    print(f'Fitted evidence index: {len(chunks)} passages, {len(artifact["vocabulary"])} terms.')


if __name__=='__main__':main()
